+  targetRotX = 0.28;
+  board.rotation.set(targetRotX, targetRotY, 0);
+  fitCamera();
+  updateHud();
+  ui.hint.textContent = 'Tap a blaster to fire';
+  ui.status.textContent = `Level ${levelNumber}: ${state.level.name}. ${totalBlocks} blocks.`;
+}
