87: function makeShape(config) {
88:   const out = [];
89:   const n = config.size;
90:   if (config.shape === 'cube') {
91:     for (let y = 0; y < n; y++) for (let z = 0; z < n; z++) for (let x = 0; x < n; x++) out.push([x, y, z]);
92:   } else if (config.shape === 'pyramid') {
93:     for (let y = 0; y < n; y++) {
94:       const span = n - y;
95:       const start = Math.floor(y / 2);
96:       for (let z = start; z < start + span; z++) for (let x = start; x < start + span; x++) out.push([x, y, z]);
97:     }
98:   } else {
99:     const mid = Math.floor((n - 1) / 2);
100:     for (let y = 0; y < n; y++) for (let z = 0; z < n; z++) for (let x = 0; x < n; x++) {
101:       if (x === mid || y === mid || z === mid) out.push([x, y, z]);
102:     }
103:   }
104:   return out;
105: }
