107: function colorFor(x, y, z, seed) {
108:   // Spatial bands make readable, chunky color clusters without isolating any piece.
109:   const pattern = (x * 3 + y * 5 + z * 2 + Math.floor((x + z) / 2) + seed) % 6;
110:   return PALETTE[pattern];
111: }
