136:   const mesh = new THREE.Mesh(new RoundedBoxGeometry(CELL * 0.94, CELL * 0.94, CELL * 0.94, 2, 0.075), material);
137:   mesh.position.copy(cellPosition(x, y, z));
138:   mesh.castShadow = true; mesh.receiveShadow = true;
139:   mesh.userData.key = key;
140:   const edge = new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.BoxGeometry(CELL * 0.86, CELL * 0.86, CELL * 0.86)), new THREE.LineBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.18 }));
141:   mesh.add(edge);
142:   board.add(mesh); blockMeshes.set(key, mesh);
143: }
