151:   for (const item of blasters) { world.remove(item.group); item.group.traverse((child) => { child.geometry?.dispose(); child.material?.dispose(); }); }
152:   blasters.length = 0;
153:   for (const item of projectiles) { world.remove(item.mesh); item.mesh.geometry.dispose(); item.mesh.material.dispose(); }
154:   projectiles.length = 0;
155:   for (const item of bursts) { world.remove(item.mesh); item.mesh.geometry.dispose(); item.mesh.material.dispose(); }
156:   bursts.length = 0;
