161: function makePlatform(level) {
162:   const radius = Math.max(level.width, level.depth) * CELL * 0.78 + 0.9;
163:   const platformY = -(level.height - 1) * CELL * 0.5 - 0.7;
164:   const base = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius * 0.94, 0.32, 64), new THREE.MeshStandardMaterial({ color: 0xfffcf6, roughness: 0.48 }));
165:   base.position.y = platformY; base.castShadow = true; base.receiveShadow = true; board.add(base);
166:   const trim = new THREE.Mesh(new THREE.TorusGeometry(radius * 0.97, 0.045, 10, 64), new THREE.MeshStandardMaterial({ color: 0xf0d8c8, roughness: 0.4 }));
167:   trim.rotation.x = Math.PI / 2; trim.position.y = platformY + 0.07; board.add(trim);
168:   const foot = new THREE.Mesh(new THREE.CylinderGeometry(radius * 0.69, radius * 0.82, 0.32, 48), new THREE.MeshStandardMaterial({ color: 0xe9ddd2, roughness: 0.58 }));
169:   foot.position.y = platformY - 0.26; foot.castShadow = true; board.add(foot);
170:   return { radius, platformY };
171: }
