173: function makeBlaster(color, angle, radius, platformY) {
174:   const group = new THREE.Group();
175:   const x = Math.sin(angle) * radius, z = Math.cos(angle) * radius;
176:   group.position.set(x, platformY + 0.2, z);
177:   group.rotation.y = -angle;
178:   group.userData.color = color;
179:   const dark = new THREE.MeshStandardMaterial({ color: 0x645e6b, roughness: 0.4, metalness: 0.14 });
180:   const body = new THREE.Mesh(new THREE.CylinderGeometry(0.19, 0.22, 0.28, 24), dark);
181:   body.position.y = 0.12; body.castShadow = true; group.add(body);
182:   const collar = new THREE.Mesh(new THREE.CylinderGeometry(0.15, 0.18, 0.22, 24), new THREE.MeshStandardMaterial({ color: color.hex, roughness: 0.3 }));
183:   collar.position.set(0, 0.31, 0); collar.castShadow = true; group.add(collar);
184:   const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.12, 0.43, 20), new THREE.MeshStandardMaterial({ color: color.hex, roughness: 0.27, metalness: 0.08 }));
185:   barrel.rotation.x = Math.PI / 2; barrel.position.set(0, 0.36, 0.2); barrel.castShadow = true; group.add(barrel);
186:   const muzzle = new THREE.Mesh(new THREE.TorusGeometry(0.105, 0.035, 8, 24), new THREE.MeshStandardMaterial({ color: 0xfff8ec, emissive: color.hex, emissiveIntensity: 0.3 }));
187:   muzzle.position.set(0, 0.36, 0.42); muzzle.add(new THREE.PointLight(color.hex, 0.5, 1.1)); group.add(muzzle);
188:   const glow = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.24, 0.025, 32), new THREE.MeshBasicMaterial({ color: color.hex, transparent: true, opacity: 0.22 }));
189:   glow.position.y = -0.035; group.add(glow);
190:   const hit = new THREE.Mesh(new THREE.SphereGeometry(0.43, 16, 12), new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false }));
191:   hit.position.y = 0.22; hit.userData.hitArea = true; group.add(hit);
192:   board.add(group);
193:   blasters.push({ group, color });
194: }
