219: function makeLevel(index, keepScore = true) {
220:   busy = false; combo = 0; ui.combo.classList.remove('show');
221:   clearWorld();
222:   levelIndex = index % LEVELS.length;
223:   state.level = { ...LEVELS[levelIndex] };
224:   if (state.level.shape === 'pyramid') { state.level.width = state.level.size; state.level.depth = state.level.size; state.level.height = state.level.size; }
225:   else { state.level.width = state.level.size; state.level.depth = state.level.size; state.level.height = state.level.size; }
226:   const coords = makeShape(state.level);
227:   const seed = levelNumber + levelIndex * 3;
228:   for (const [x, y, z] of coords) cells.set(keyOf(x, y, z), colorFor(x, y, z, seed));
229:   for (const [key, color] of cells) createBlock(key, color);
230:   state.components = findComponents();
231:   totalBlocks = cells.size; clearedBlocks = 0;
232:   movesLeft = state.components.length + Math.max(2, Math.ceil(state.components.length * 0.16));
233:   if (!keepScore) { score = 0; levelScore = 0; }
234:   else levelScore = 0;
235:   const { radius, platformY } = makePlatform(state.level);
236:   const colors = [...new Set(state.components.map((component) => component.color))];
237:   colors.forEach((color, i) => makeBlaster(color, (i / colors.length) * Math.PI * 2, radius * 0.82, platformY));
238:   targetRotY = -0.38;
239:   targetRotX = 0.28;
240:   board.rotation.set(targetRotX, targetRotY, 0);
241:   fitCamera();
242:   updateHud();
243:   ui.hint.textContent = 'Tap a blaster to fire';
244:   ui.status.textContent = `Level ${levelNumber}: ${state.level.name}. ${totalBlocks} blocks.`;
245: }
