247: function fitCamera() {
248:   const rect = ui.canvas.getBoundingClientRect();
249:   if (!rect.width || !rect.height) return;
250:   const aspect = rect.width / rect.height;
251:   const maxSpan = Math.max(state.level.width, state.level.depth) * CELL;
252:   const worldWidth = maxSpan + 2.4;
253:   const viewHeight = Math.max(5.8, worldWidth / aspect);
254:   camera.left = -viewHeight * aspect / 2; camera.right = viewHeight * aspect / 2;
255:   camera.top = viewHeight / 2; camera.bottom = -viewHeight / 2;
256:   camera.position.set(6, 8, 10).multiplyScalar(Math.max(1, maxSpan / 3));
257:   camera.lookAt(0, -0.2, 0);
258:   camera.updateProjectionMatrix();
259: }
