261: function componentCenter(component) {
262:   const center = new THREE.Vector3();
263:   for (const key of component.keys) {
264:     const [x, y, z] = coordsFromKey(key);
265:     center.add(cellPosition(x, y, z));
266:   }
267:   return center.multiplyScalar(1 / component.keys.length);
268: }
