270: function findTarget(color, shooter) {
271:   board.updateMatrixWorld(true);
272:   const from = new THREE.Vector3(); shooter.getWorldPosition(from);
273:   let best = null, bestDistance = Infinity;
274:   for (const component of state.components) {
275:     if (component.color !== color) continue;
276:     const center = componentCenter(component);
277:     const worldCenter = board.localToWorld(center.clone());
278:     const distance = from.distanceTo(worldCenter);
279:     if (distance < bestDistance) { bestDistance = distance; best = { component, center }; }
280:   }
281:   return best;
282: }
