284: function playTone(frequency = 480, duration = 0.11, type = 'sine', volume = 0.045) {
285:   if (!soundOn) return;
286:   try {
287:     audioContext ??= new (window.AudioContext || window.webkitAudioContext)();
288:     if (audioContext.state === 'suspended') audioContext.resume();
289:     const oscillator = audioContext.createOscillator();
290:     const gain = audioContext.createGain();
291:     oscillator.type = type; oscillator.frequency.setValueAtTime(frequency, audioContext.currentTime);
292:     oscillator.frequency.exponentialRampToValueAtTime(Math.max(80, frequency * 0.62), audioContext.currentTime + duration);
293:     gain.gain.setValueAtTime(volume, audioContext.currentTime);
294:     gain.gain.exponentialRampToValueAtTime(0.001, audioContext.currentTime + duration);
295:     oscillator.connect(gain); gain.connect(audioContext.destination);
296:     oscillator.start(); oscillator.stop(audioContext.currentTime + duration);
297:   } catch { /* Audio is an optional flourish; gameplay never depends on it. */ }
298: }
