342:   const mesh = new THREE.Mesh(new THREE.SphereGeometry(0.16, 20, 16), new THREE.MeshStandardMaterial({ color: blaster.color.hex, emissive: blaster.color.hex, emissiveIntensity: 0.5, roughness: 0.22 }));
343:   mesh.position.copy(origin); board.add(mesh);
344:   const glow = new THREE.PointLight(blaster.color.hex, 1.8, 2.3); mesh.add(glow);
345:   projectiles.push({ mesh, from: origin, to: target.center.clone(), component: target.component, color: blaster.color, elapsed: 0, duration: 0.42 });
