349: function beginClusterClear(component, color, center) {
350:   combo++;
351:   const multiplier = Math.min(2.5, 1 + (combo - 1) * 0.25);
352:   const points = Math.round(component.keys.length * 100 * multiplier);
353:   score += points; levelScore += points;
354:   clearedBlocks += component.keys.length;
355:   showFloat(center, points, color, combo > 1 ? `${combo}× combo` : `${component.keys.length} cubes`);
356:   if (combo > 1) {
357:     ui.comboValue.textContent = multiplier.toFixed(2);
358:     ui.combo.classList.add('show');
359:     clearTimeout(comboTimer);
360:     comboTimer = setTimeout(() => ui.combo.classList.remove('show'), 1550);
361:   }
362:   playTone(610 + Math.min(component.keys.length, 10) * 24, 0.24, 'sine', 0.06);
363:   makeBurst(center, color, Math.min(34, 12 + component.keys.length * 2));
364:   for (const key of component.keys) {
365:     const mesh = blockMeshes.get(key);
366:     if (!mesh) continue;
367:     const [x, y, z] = coordsFromKey(key);
368:     const from = mesh.position.clone();
369:     const scatter = new THREE.Vector3((x - (state.level.width - 1) / 2) * 0.16, 0.12 + Math.random() * 0.35, (z - (state.level.depth - 1) / 2) * 0.16);
370:     removeAfterAnimation.push({ key, mesh, from, to: from.clone().add(scatter), age: 0, duration: 0.43 + Math.random() * 0.12 });
371:   }
372:   updateHud();
373:   ui.status.textContent = `Cleared ${component.keys.length} ${color.name} cubes for ${points} points.`;
374:   setTimeout(() => finishClusterClear(component, color), 510);
375: }
