377: function finishClusterClear(component, color) {
378:   for (const key of component.keys) {
379:     const mesh = blockMeshes.get(key);
380:     if (mesh) {
381:       board.remove(mesh); mesh.geometry.dispose();
382:       mesh.children.forEach((child) => { child.geometry?.dispose(); child.material?.dispose(); });
383:       mesh.material.dispose(); blockMeshes.delete(key);
384:     }
385:     cells.delete(key);
386:   }
387:   state.components = findComponents();
388:   for (let i = blasters.length - 1; i >= 0; i--) {
389:     if (!state.components.some((part) => part.color === blasters[i].color)) {
390:       const [removed] = blasters.splice(i, 1);
391:       board.remove(removed.group);
392:       removed.group.traverse((child) => { child.geometry?.dispose(); child.material?.dispose(); });
393:     }
394:   }
395:   updateHud();
396:   if (!cells.size) {
397:     busy = false;
398:     finishLevel(true);
399:   } else {
400:     busy = false;
401:     ui.hint.textContent = 'Tap a blaster to fire';
402:     showToast(`${component.keys.length} ${color.name.toLowerCase()} cubes cleared`);
403:     if (movesLeft <= 0) finishLevel(false);
404:   }
405: }
