436: ui.canvas.addEventListener('pointerdown', (event) => {
437:   if (event.button !== undefined && event.button !== 0) return;
438:   drag = { id: event.pointerId, x: event.clientX, y: event.clientY, lastX: event.clientX, lastY: event.clientY, moved: false };
439:   ui.canvas.classList.add('dragging');
440:   ui.canvas.setPointerCapture?.(event.pointerId);
441: });
442: ui.canvas.addEventListener('pointermove', (event) => {
443:   if (!drag || drag.id !== event.pointerId) return;
444:   const dx = event.clientX - drag.lastX, dy = event.clientY - drag.lastY;
445:   if (Math.hypot(event.clientX - drag.x, event.clientY - drag.y) > 5) drag.moved = true;
446:   if (drag.moved) {
447:     targetRotY += dx * 0.008;
448:     targetRotX = THREE.MathUtils.clamp(targetRotX + dy * 0.006, -0.22, 0.82);
449:   }
450:   drag.lastX = event.clientX; drag.lastY = event.clientY;
451: });
452: ui.canvas.addEventListener('pointerup', (event) => {
453:   if (!drag || drag.id !== event.pointerId) return;
454:   const wasDrag = drag.moved;
455:   drag = null; ui.canvas.classList.remove('dragging');
456:   if (wasDrag) return;
457:   const rect = renderer.domElement.getBoundingClientRect();
458:   pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
459:   pointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
460:   raycaster.setFromCamera(pointer, camera);
461:   const hits = raycaster.intersectObjects(blasters.map((item) => item.group), true);
462:   for (const hit of hits) {
463:     let node = hit.object;
464:     while (node && !node.userData.color) node = node.parent;
465:     if (node?.userData.color) {
466:       const shooter = blasters.find((item) => item.group === node);
467:       if (shooter) fireBlaster(shooter);
468:       break;
469:     }
470:   }
471: });
472: ui.canvas.addEventListener('pointercancel', () => { drag = null; ui.canvas.classList.remove('dragging'); });
473: ui.canvas.addEventListener('keydown', (event) => {
474:   if (event.key === 'ArrowLeft') targetRotY -= 0.2;
475:   if (event.key === 'ArrowRight') targetRotY += 0.2;
476:   if (event.key === 'ArrowUp') targetRotX = THREE.MathUtils.clamp(targetRotX - 0.12, -0.22, 0.82);
477:   if (event.key === 'ArrowDown') targetRotX = THREE.MathUtils.clamp(targetRotX + 0.12, -0.22, 0.82);
478:   if (/^[1-6]$/.test(event.key)) fireBlaster(blasters[Number(event.key) - 1]);
479: });
